const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const svixId = headers['svix-id'] || headers['webhook-id'];
const svixTimestamp = headers['svix-timestamp'] || headers['webhook-timestamp'];
const svixSignature = headers['svix-signature'] || headers['webhook-signature'];
let payload;
if (item.binary && item.binary.data && item.binary.data.data) {
  payload = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  payload = JSON.stringify(item.json.body);
}
const secret = $env.RESEND_INBOUND_SECRET || '';
const out = (valid, reason) => [{ json: { valid, reason, payload } }];
if (!secret) return out(false, 'missing_secret');
if (!svixId || !svixTimestamp || !svixSignature) return out(false, 'missing_headers');
const now = Math.floor(Date.now() / 1000);
const ts = parseInt(svixTimestamp, 10);
if (!Number.isFinite(ts) || Math.abs(now - ts) > 300) return out(false, 'timestamp_out_of_tolerance');
const secretBytes = Buffer.from(secret.replace(/^whsec_/, ''), 'base64');
const signedContent = svixId + '.' + svixTimestamp + '.' + payload;
const expected = crypto.createHmac('sha256', secretBytes).update(signedContent).digest('base64');
const passed = String(svixSignature).split(' ').some(function (part) {
  const sig = part.indexOf(',') !== -1 ? part.split(',')[1] : part;
  if (!sig || sig.length !== expected.length) return false;
  try { return crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected)); } catch (e) { return false; }
});
return out(passed, passed ? 'ok' : 'signature_mismatch');
